import React, {Component} from "react";
import rescued from '../assets/rescued.jpg'
import { Adopt } from "./adopt";

export class OurPets extends Component {
    componentDidMount() {
        if (!document.querySelector('script[src="https://www.petfinder.com/pet-scroller.bundle.js"]')) {
            const script = document.createElement("script");
            script.src = "https://www.petfinder.com/pet-scroller.bundle.js";
            script.async = true;
            document.body.appendChild(script);
        }
    }

    render(){
        let rows = null;
        if (this.props.animals != null && this.props.animals.length > 0) {
            rows = (
                <div className="row ourpets">
                    {this.props.animals.map((p, i) => {
                        let imgsrc = null;
                        if (p.photos != null && p.photos.length > 0 && p.photos[0].medium != null) {
                            imgsrc = <img style={{width: "100%"}} src={p.photos[0].medium} alt="" />;
                        }
                        return (
                            <div className="col-xs-12 col-sm-6 col-xl-3" key={i}>
                                <a href={p.url} target="blank">
                                    <div className="petname">{p.name}</div>
                                    <div>{imgsrc}</div>
                                </a>
                            </div>
                        );
                    })}
                </div>
            );
        }

        return (
          <React.Fragment>
            <div className="row">
              <div className="col-12">
                <h5>
                  Thousands of homeless kittens &amp; cats rescued locally and
                  placed in forever homes. Have fun looking at the recently
                  rescued cuties waiting to purr in your ear.
              </h5>
              </div>
              <div className="col-12 col-xl-9">
                <img className="width100" src={rescued} alt="" />
                <br />
                <br />
              </div>
              <div className="col-12 col-xl-3">
                <Adopt />
                <br />
                <br />
              </div>
              <div className="col-12">
                <h5>Here are our adoptable animals</h5>
                <br />
              </div>
            </div>
            {rows}
            <div className="pet-list-widget-section" style={{ width: "100%", margin: "15px 0 30px 0" }}>
              {/* Pet List Widget - Start */}
              <pet-scroller
                s3Url="https://dbw3zep4prcju.cloudfront.net/"
                apiBase="https://psl.petfinder.com/graphql"
                organization='["NJ523"]'
                status="adoptable"
                petfinderUrl="https://www.petfinder.com/"
                type='["cat"]'
                hideBreed="true"
                limit="24"
                petListTitle=""
              ></pet-scroller>
              {/* Pet List Widget - End */}
            </div>
          </React.Fragment>
        );
    }
}

